    fact[0] = 1;
    for (int i = 1; i < MAXN; i++) fact[i] = (long long)fact[i - 1] * i % p;
    inv_fact[MAXN - 1] = pow(fact[MAXN - 1], p - 2, p);
    for (int i = MAXN - 2; i >= 0; i--) inv_fact[i] = (long long)inv_fact[i + 1] * (i + 1) % p;
    vector<int> a(temp_n + 1, 0);
    for (int i = 0; i <= temp_n; i++) a[i] = inv_fact[f[i]];
    int res = pow(k, n) % p;
    a = subset_power_convolution(a, k, p);
    int subtract_value = (long long)a[temp_n] * fact[n] % p;
    res = (res - subtract_value + p) % p;
    cout << res << "\n";
    return 0;
}
